<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { CalendarDays, Check, ImagePlus, Plus, Save, Settings2, Trash2 } from 'lucide-vue-next'
import { addCategory, deleteCategory, fetchCategories, fetchSettings, saveSettings, type Category, type MenuTheme } from '../services/settings'
const themes:{id:MenuTheme;name:string;description:string;colors:string[]}[]=[
  {id:'classic',name:'Klasik',description:'Sıcak ve zarif',colors:['#19211d','#e86e35','#f6f4ef']},{id:'modern',name:'Modern',description:'Sade ve net',colors:['#171717','#a3e635','#fafafa']},{id:'ocean',name:'Okyanus',description:'Ferah ve huzurlu',colors:['#0b3440','#20a4a9','#edf8f7']},{id:'terracotta',name:'Terracotta',description:'Doğal ve samimi',colors:['#552c24','#c86442','#fff5ea']},{id:'midnight',name:'Gece',description:'Premium ve şık',colors:['#10131e','#d5ae5e','#171b29']},{id:'pastel',name:'Pastel',description:'Yumuşak ve neşeli',colors:['#543b55','#dd7694','#fff2f4']}]
const loading=ref(true),saving=ref(false),saved=ref(false),error=ref(''),company=ref(''),menuTitle=ref(''),logo=ref(''),banner=ref(''),theme=ref<MenuTheme>('classic'),categories=ref<Category[]>([]),newCategory=ref('')
const licenseStart=ref(''),licenseEnd=ref(''),days=ref(0),progress=computed(()=>Math.max(0,Math.min(100,(days.value/365)*100)))
const date=(v:string)=>v?new Intl.DateTimeFormat('tr-TR',{day:'2-digit',month:'long',year:'numeric'}).format(new Date(v)):'—'
onMounted(async()=>{try{const [s,c]=await Promise.all([fetchSettings(),fetchCategories()]);company.value=s.company;menuTitle.value=s.menuTitle;logo.value=s.logo||'';banner.value=s.banner||'';theme.value=s.theme||'classic';licenseStart.value=s.licenseStart;licenseEnd.value=s.licenseEnd;days.value=s.licenseDaysRemaining;categories.value=c}catch(e){error.value=e instanceof Error?e.message:'Bilgiler alınamadı'}finally{loading.value=false}})
function image(event:Event,target:'logo'|'banner'){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;if(file.size>2*1024*1024){error.value='Görsel en fazla 2 MB olabilir.';return}const reader=new FileReader();reader.onload=()=>target==='logo'?logo.value=String(reader.result):banner.value=String(reader.result);reader.readAsDataURL(file)}
async function save(){saving.value=true;error.value='';try{const s=await saveSettings({company:company.value,menuTitle:menuTitle.value,logo:logo.value||undefined,banner:banner.value||undefined,theme:theme.value});localStorage.setItem('qr-menu-user',JSON.stringify(s));saved.value=true;setTimeout(()=>saved.value=false,1800)}catch(e){error.value=e instanceof Error?e.message:'Kaydedilemedi'}finally{saving.value=false}}
async function createCategory(){const name=newCategory.value.trim();if(!name)return;try{const item=await addCategory(name);if(!categories.value.some(c=>c.id===item.id))categories.value.push(item);newCategory.value=''}catch(e){error.value=e instanceof Error?e.message:'Kategori eklenemedi'}}
async function removeCategory(item:Category){if(!confirm(`“${item.name}” kategorisi silinsin mi?`))return;await deleteCategory(item.id);categories.value=categories.value.filter(c=>c.id!==item.id)}
</script>
<template><div class="settings-page"><header><span>MENÜ AYARLARI</span><h2>Lisans ve görünüm</h2><p>Kategorileri ve QR menünüzün kurumsal görünümünü yönetin.</p></header><p v-if="error" class="settings-error">{{error}}</p><div v-if="loading" class="settings-loading">Bilgiler yükleniyor...</div><template v-else>
<section class="license-card"><div class="license-icon"><CalendarDays :size="25"/></div><div class="license-main"><div><span>YILLIK LİSANS</span><h3>{{days}} gün kaldı</h3><p>{{date(licenseStart)}} — {{date(licenseEnd)}}</p></div><b :class="{warning:days<30}">{{days>0?'AKTİF':'SÜRESİ DOLDU'}}</b><div class="license-bar"><i :style="{width:progress+'%'}"></i></div></div></section>
<section class="settings-card theme-section"><div class="card-title"><Settings2 :size="20"/><div><h3>Menü temanızı seçin</h3><p>Müşterilerinizin QR menüde göreceği tasarımı belirleyin.</p></div></div><div class="theme-grid"><button v-for="item in themes" :key="item.id" type="button" class="theme-option" :class="[{selected:theme===item.id},`option-${item.id}`]" @click="theme=item.id"><span class="theme-preview" :class="`preview-${item.id}`" :style="{'--preview-dark':item.colors[0],'--preview-accent':item.colors[1],'--preview-bg':item.colors[2]}"><i></i><em></em><small></small><span></span></span><span class="theme-copy"><b>{{item.name}}</b><small>{{item.description}}</small></span><Check v-if="theme===item.id" :size="17"/></button></div></section>
<div class="settings-grid"><section class="settings-card"><div class="card-title"><Settings2 :size="20"/><div><h3>Kategoriler (Gruplar)</h3><p>İstediğiniz kategori adını oluşturun.</p></div></div><form class="category-add" @submit.prevent="createCategory"><input v-model="newCategory" placeholder="Örn. Kahvaltılar"/><button><Plus :size="17"/> Ekle</button></form><div class="category-list"><div v-for="item in categories" :key="item.id"><span>{{item.name}}</span><button @click="removeCategory(item)" title="Sil"><Trash2 :size="15"/></button></div><p v-if="!categories.length">Henüz kategori yok.</p></div></section>
<section class="settings-card branding"><div class="card-title"><ImagePlus :size="20"/><div><h3>QR Menü görünümü</h3><p>Şirket adı, logo ve banner görselini değiştirin.</p></div></div><label>Şirket adı<input v-model="company"/></label><label>Menü başlığı<input v-model="menuTitle" placeholder="Restoranınızın adı"/></label><div class="upload-grid"><label class="image-upload"><span>Logo</span><input type="file" accept="image/*" @change="image($event,'logo')"/><img v-if="logo" :src="logo"/><i v-else><ImagePlus :size="20"/> Görsel seç</i></label><label class="image-upload"><span>Banner</span><input type="file" accept="image/*" @change="image($event,'banner')"/><img v-if="banner" :src="banner"/><i v-else><ImagePlus :size="20"/> Görsel seç</i></label></div><button class="save-settings" :disabled="saving" @click="save"><Check v-if="saved" :size="17"/><Save v-else :size="17"/>{{saved?'Kaydedildi':saving?'Kaydediliyor...':'Ayarları kaydet'}}</button></section></div></template></div></template>
<style scoped>
