}.theme-preview{position:relative;width:70px;height:49px;flex:0 0 70px;border-radius:8px;overflow:hidden;border:1px solid #0001}.theme-preview i{display:block;height:17px}.theme-preview em{position:absolute;width:8px;height:8px;border-radius:50%;left:8px;top:5px}.theme-preview small{position:absolute;left:8px;right:8px;bottom:7px;height:15px;border:1px solid;border-radius:3px;background:#fffc}.card-title{display:flex;align-items:center;gap:11px;margin-bottom:20px}.card-title>svg{color:var(--orange)}.card-title h3{font-size:16px;margin:0 0 4px}.category-add{display:flex;gap:8px}.category-add input,.branding>label input{height:43px;border:1px solid #dce0dc;border-radius:10px;padding:0 12px;outline:none}.category-add input{flex:1;min-width:0}.category-add button,.save-settings{border:0;background:#202522;color:#fff;border-radius:10px;padding:0 15px;font-weight:700;display:flex;align-items:center;gap:6px}.category-list{margin-top:14px;display:grid;gap:7px}.category-list>div{height:42px;background:#f6f8f5;border-radius:9px;padding:0 10px 0 13px;display:flex;align-items:center;justify-content:space-between;font-size:11px;font-weight:700}.category-list button{border:0;background:none;color:#dc604f;cursor:pointer}.branding>label{display:grid;gap:6px;font-size:10px;font-weight:700;margin-bottom:12px}.upload-grid{display:grid;grid-template-columns:140px 1fr;gap:12px}.image-upload{height:120px;border:1px dashed #cfd5d0;border-radius:12px;overflow:hidden;position:relative;cursor:pointer}.image-upload>span{position:absolute;z-index:2;top:7px;left:7px;background:#18201dcc;color:#fff;padding:4px 7px;border-radius:5px;font-size:8px}.image-upload input{display:none}.image-upload img{width:100%;height:100%;object-fit:cover}.image-upload i{height:100%;display:flex;align-items:center;justify-content:center;gap:5px;color:#8e9790;font-size:9px;font-style:normal}.save-settings{height:44px;margin:18px 0 0 auto;cursor:pointer}@media(max-width:850px){.settings-grid{grid-template-columns:1fr}.theme-grid{grid-template-columns:repeat(2,1fr)}.license-main{grid-template-columns:1fr}.license-bar{grid-column:1}.upload-grid{grid-template-columns:1fr}.image-upload{height:150px}}@media(max-width:520px){.theme-grid{grid-template-columns:1fr}}
/* Distinct theme thumbnails */
.settings-page{display:flex;flex-direction:column}.license-card{order:1}.settings-grid{order:2}.theme-section{order:3;margin-top:18px;margin-bottom:0}
.theme-section .theme-grid{gap:14px}.theme-section .theme-option{display:block;text-align:left;padding:9px 9px 13px;border-radius:16px;overflow:hidden;transition:.22s}.theme-section .theme-option:hover{transform:translateY(-3px);box-shadow:0 9px 24px #e86e3520}.theme-section .theme-option>svg{right:16px;top:auto;bottom:16px}.theme-section .theme-copy{display:grid;gap:4px;padding:11px 7px 0}.theme-section .theme-preview{--preview-dark:#222;--preview-accent:#e86e35;--preview-bg:#f5f5f5;position:relative;display:block;width:100%;height:105px;background:var(--preview-bg);border-radius:10px;overflow:hidden}.theme-section .theme-preview i,.theme-section .theme-preview em,.theme-section .theme-preview small,.theme-section .theme-preview>span{position:absolute;display:block}.theme-section .theme-preview i{left:0;right:0;top:0;height:38px;background:var(--preview-dark)}.theme-section .theme-preview em{width:12px;height:12px;border-radius:50%;left:10px;top:9px;background:var(--preview-accent)}.theme-section .theme-preview small{left:10px;right:52%;top:49px;height:39px;border:0;background:#fff;box-shadow:0 2px 6px #0001}.theme-section .theme-preview>span{left:52%;right:10px;top:49px;height:39px;background:#fff;box-shadow:0 2px 6px #0001}
.theme-section .preview-modern{border-radius:2px}.theme-section .preview-modern i{height:28px}.theme-section .preview-modern em{border-radius:0;width:28px;height:5px;top:12px}.theme-section .preview-modern small{left:0;right:0;top:36px;height:20px;box-shadow:none;border-bottom:2px solid var(--preview-dark)}.theme-section .preview-modern>span{left:0;right:0;top:62px;height:20px;box-shadow:none;border-bottom:2px solid var(--preview-dark)}
.theme-section .preview-ocean{border-radius:10px 10px 28px 28px}.theme-section .preview-ocean small{border-radius:5px 18px 5px 18px}.theme-section .preview-ocean>span{border-radius:18px 5px 18px 5px}.theme-section .preview-terracotta i{height:100%}.theme-section .preview-terracotta em{width:48px;height:5px;border-radius:5px;top:18px}.theme-section .preview-terracotta small{left:12px;right:56%;top:39px;height:52px;border-radius:18px;background:var(--preview-bg)}.theme-section .preview-terracotta>span{left:52%;right:12px;top:39px;height:52px;border-radius:18px;background:var(--preview-bg)}
